\section{Introduction}

\subsection{The conflation}
Let $x=(x_0,x_1,x_2,\dots)$ be a sequence of decimal digits. The standard sonification maps $x_i$ to the $x_i$-th note of a scale, producing a \emph{digit melody}. Two numerical quantities then compete for the name ``twelve''.

The \emph{temporal lag} $\ell$ is the offset used when comparing positions: the pair $(i,i+\ell)$. It parameterizes the autocorrelation $A(\ell)=\sum_i x_ix_{i+\ell}$ and lives in the additive monoid $(\N,+)$ of offsets. The \emph{pitch interval} is the perceptual distance between two notes in semitones, $|x_i-x_j|$; an \emph{octave} is the interval value $12$.

The two coincide only in name. A lag-$12$ autocorrelation compares digit positions twelve time steps apart; it does not measure a twelve-semitone interval. This paper gives a complete mathematical treatment of the separation and finds, as often happens when a conflation is corrected, that both variables are interesting on their own.

\subsection{Contributions}
\begin{enumerate}[label=(\arabic*)]
\item Support of the interval distribution and the vanishing octave (\S3).
\item A moment calculus: every additive lag statistic is a moment of the interval distribution (\S3.3).
\item The moment bridge $2A(k)=2E-\sum_v v^2N_k(v)$ and its non-invertibility (\S5).
\item An exact combinatorial null model and the null autocorrelation deficit law (\S6).
\item The tropical lag spectrum, gcd-rigidity of the unison-lag monoid, and a complete dichotomy at lag twelve (\S7).
\item An inverse theorem realizing arbitrary interval histograms at arbitrary lags (\S8).
\item Tropical idempotency of the interval matrix (\S9), and faithfulness of pitch classes below base $13$ (\S10).
\end{enumerate}

\section{Setting and basic definitions}

Throughout, $b\ge1$ is an alphabet size and a \emph{melody} is a function $x:\N\to\N$.

\begin{definition}
$x$ is a \emph{base-$b$ digit melody} if $x_i<b$ for all $i$; we write $x\in\mathcal D_b$. The decimal case is $b=10$.
\end{definition}

\begin{definition}
The \emph{pitch interval} between positions $i$ and $j$ is $\iota_x(i,j)=|x_i-x_j|$. The \emph{lag-$\ell$ interval at position $i$} is $\lambda_x(\ell,i)=\iota_x(i,i+\ell)$. The \emph{interval distribution} is
\[ N_x(n,\ell,v)=\#\{\, i<n : \lambda_x(\ell,i)=v \,\}. \]
\end{definition}

Elementary properties: $\iota_x$ is symmetric, $\iota_x(i,i)=0$, $\iota_x(i,j)=0\iff x_i=x_j$, $\lambda_x(0,i)=0$, and the triangle inequality
\begin{equation}\label{eq:tri}
\iota_x(i,k)\le \iota_x(i,j)+\iota_x(j,k)
\end{equation}
holds for all $i,j,k$, since $|\cdot|$ is a metric on $\Z$. Inequality \eqref{eq:tri} is the single analytic input behind everything tropical below.

For cyclic statistics, let $d:\Z/n\to\{0,\dots,b-1\}$ and set
\[ E(d)=\sum_i d_i^2,\qquad A_d(k)=\sum_i d_id_{i+k},\qquad \mathcal I_d(k)=\sum_i(d_{i+k}-d_i)^2, \]
the \emph{energy}, \emph{autocorrelation at lag $k$} and \emph{interval energy at lag $k$}; and let $N^{\mathrm{cyc}}_d(k,v)=\#\{i\in\Z/n : |d_i-d_{i+k}|=v\}$. Expanding the square and reindexing the cycle gives the polarization identity
\begin{equation}\label{eq:pol}
2A_d(k)=2E(d)-\mathcal I_d(k).
\end{equation}

\section{The interval distribution: support, mass, moments}

\begin{lemma}\label{lem:lt}
If $x\in\mathcal D_b$ then $\lambda_x(\ell,i)<b$ for all $\ell,i$.
\end{lemma}
\begin{proof} Both $x_i$ and $x_{i+\ell}$ lie in $[0,b)$, so their absolute difference is $<b$. \end{proof}

\begin{theorem}[Support]\label{thm:supp}
If $x\in\mathcal D_b$ and $v\ge b$ then $N_x(n,\ell,v)=0$ for all $n,\ell$.
\end{theorem}
\begin{proof} Immediate from Lemma~\ref{lem:lt}: the defining filter is empty. \end{proof}

\begin{corollary}[The octave never appears]\label{cor:oct}
For every decimal melody $x$, every window length $n$, and every lag $\ell$ --- in particular $\ell=12$ --- one has $N_x(n,\ell,12)=0$.
\end{corollary}

\begin{corollary}[Octave versus unison at lag twelve]
For a decimal melody, $N_x(n,12,12)=0$ while $N_x(n,12,0)=\#\{i<n : x_i=x_{i+12}\}$. These are different statistics of the same $n$ position pairs; the first is identically zero, the second is what a lag-$12$ correlation study detects.
\end{corollary}

\begin{theorem}[Total mass]\label{thm:mass}
For $x\in\mathcal D_b$, $\ \sum_{v=0}^{b-1}N_x(n,\ell,v)=n$.
\end{theorem}
\begin{proof} Partition $\{0,\dots,n-1\}$ into the fibres of $i\mapsto\lambda_x(\ell,i)$, which lands in $\{0,\dots,b-1\}$ by Lemma~\ref{lem:lt}. \end{proof}

\begin{theorem}[Moment principle]\label{thm:mom}
For $x\in\mathcal D_b$ and any weight $g:\N\to\N$,
\[ \sum_{v=0}^{b-1} g(v)\,N_x(n,\ell,v)=\sum_{i<n} g\bigl(\lambda_x(\ell,i)\bigr). \]
\end{theorem}
\begin{proof} Fibrewise summation as in Theorem~\ref{thm:mass}, with $g$ constant on each fibre. \end{proof}

\begin{corollary}
$\sum_{v} v^2N_x(n,\ell,v)=\sum_{i<n}\lambda_x(\ell,i)^2$; and for $x\in\mathcal D_{10}$ this is at most $81n$, with equality iff every lag-$\ell$ interval in the window is nine semitones.
\end{corollary}

\section{Witness melodies}

\begin{definition}
For $v,\ell\ge0$ let the \emph{square wave} be $s_{v,\ell}(i)=v\cdot(\lfloor i/\ell\rfloor \bmod 2)$.
\end{definition}

\begin{lemma}\label{lem:sq}
If $v<b$ then $s_{v,\ell}\in\mathcal D_b$; and if $\ell\ge1$ then $\lambda_{s_{v,\ell}}(\ell,i)=v$ for every $i$.
\end{lemma}
\begin{proof} The values are $0$ and $v$. Since $\lfloor(i+\ell)/\ell\rfloor=\lfloor i/\ell\rfloor+1$, the block parity flips, so exactly one of the two notes equals $v$ and the other $0$. \end{proof}

\begin{theorem}[Lag/interval spectrum]\label{thm:spec}
There is a decimal melody $x$ with $\lambda_x(\ell,i)=v$ for all $i$ if and only if $v\le 9$ and ($\ell\ge1$ or $v=0$).
\end{theorem}
\begin{proof} Necessity: $v\le9$ by Lemma~\ref{lem:lt}, and $\lambda_x(0,i)=0$ forces $v=0$ when $\ell=0$. Sufficiency: take $s_{v,\ell}$ for $\ell\ge1$ (Lemma~\ref{lem:sq}), or the constant melody for $v=0$. \end{proof}

\begin{corollary}
Every constant lag-$12$ interval value $v\le9$ --- unison up to major sixth --- is realized by a decimal melody, and no value $\ge10$ is realized at any lag. Moreover $s_{7,12}$ has, for every window length $n$, lag-$12$ counts $N(n,12,7)=n$, $N(n,12,0)=0$, $N(n,12,12)=0$: perfect temporal regularity at lag $12$ with no unison whatsoever at that lag.
\end{corollary}

\section{The moment bridge}

\begin{theorem}[Interval energy is the second moment]\label{thm:ie}
Let $d:\Z/n\to\{0,\dots,b-1\}$. Then $\mathcal I_d(k)=\sum_{v=0}^{b-1}v^2N^{\mathrm{cyc}}_d(k,v)$.
\end{theorem}
\begin{proof} Since $(d_{i+k}-d_i)^2=|d_i-d_{i+k}|^2$, fibre the index set over the value of $i\mapsto |d_i-d_{i+k}|$, which lands in $\{0,\dots,b-1\}$; on the fibre over $v$ the summand is constantly $v^2$. \end{proof}

\begin{theorem}[Moment bridge]\label{thm:bridge}
For a base-$b$ cyclic digit melody $d$ and any lag $k$,
\[ 2A_d(k)=2E(d)-\sum_{v=0}^{b-1}v^2\,N^{\mathrm{cyc}}_d(k,v). \]
\end{theorem}
\begin{proof} Combine \eqref{eq:pol} with Theorem~\ref{thm:ie}. \end{proof}

\begin{corollary}[Congruence]
If $d,e$ are base-$b$ cyclic digit melodies of the same length with $E(d)=E(e)$ and $N^{\mathrm{cyc}}_d(k,\cdot)=N^{\mathrm{cyc}}_e(k,\cdot)$, then $A_d(k)=A_e(k)$.
\end{corollary}

\begin{theorem}[Maximality is a unison statement]
$A_d(k)=E(d)$ if and only if $|d_i-d_{i+k}|=0$ for all $i$, i.e.\ the window is $k$-periodic.
\end{theorem}
\begin{proof} By \eqref{eq:pol}, $A_d(k)=E(d)$ iff $\mathcal I_d(k)=0$ iff the shifted signal equals the original. \end{proof}

Hence a lag-$12$ autocorrelation peak is a statement about the unison mass $N_{12}(0)$; by Corollary~\ref{cor:oct} the octave value contributes mass $0$ to every term of the bridge.

\begin{theorem}[Information loss]\label{thm:loss}
There are decimal cyclic melodies $d,e$ of length $4$ with $E(d)=E(e)$, $A_d(1)=A_e(1)$, and $N^{\mathrm{cyc}}_d(1,0)\ne N^{\mathrm{cyc}}_e(1,0)$.
\end{theorem}
\begin{proof} Take $d=(0,0,0,5)$ and $e=(0,3,0,4)$. Then $E(d)=25=9+16=E(e)$, and every cyclically adjacent product vanishes, so $A_d(1)=0=A_e(1)$. The lag-$1$ interval multiset of $d$ is $\{0,0,5,5\}$, so $N^{\mathrm{cyc}}_d(1,0)=2$; that of $e$ is $\{3,3,4,4\}$, so $N^{\mathrm{cyc}}_e(1,0)=0$. \end{proof}

Thus a correlation statistic cannot certify any statement about which musical intervals occur.

\section{The exact null model}

\begin{definition}
$P_b(v)=\#\{(a,c)\in\{0,\dots,b-1\}^2 : |a-c|=v\}$.
\end{definition}

\begin{theorem}[Triangular null distribution]
$P_b(0)=b$; $P_b(v)=2(b-v)$ for $0<v<b$; $P_b(v)=0$ for $v\ge b$. In particular $P_{10}(12)=0$, and $\sum_{v<b}P_b(v)=b^2$.
\end{theorem}
\begin{proof} For $v=0$ the diagonal pairs; for $0<v<b$ the pairs $(a,a+v)$ and $(a+v,a)$ with $0\le a<b-v$; the total is the partition of all ordered pairs by interval value. \end{proof}

\begin{theorem}[Null second moment]\label{thm:nullmom}
$6\sum_{v<b}v^2P_b(v)+b^2=b^4$, i.e.\ $\sum_{v<b}v^2P_b(v)=\dfrac{b^4-b^2}{6}$. In base ten the value is $1650$: a mean squared interval of exactly $16.5$ semitones$^2$ over the $100$ ordered digit pairs.
\end{theorem}
\begin{proof}[Proof sketch] The sum equals $\sum_{v=1}^{b-1}2v^2(b-v)$; substituting $\sum_{v<b}v^2=\frac{(b-1)b(2b-1)}{6}$ and $\sum_{v<b}v^3=\frac{b^2(b-1)^2}{4}$ and simplifying yields $(b^4-b^2)/6$. Formally the identity is established by induction on $b$ over the integers, avoiding truncated subtraction. \end{proof}

\begin{theorem}[Null autocorrelation deficit]\label{thm:deficit}
Let $d$ be a base-$b$ cyclic digit melody whose lag-$k$ interval distribution is exactly $m$ copies of the null distribution: $N^{\mathrm{cyc}}_d(k,v)=m\,P_b(v)$ for all $v$. Then
\[ 12\bigl(E(d)-A_d(k)\bigr)=m\,(b^4-b^2). \]
In base ten, $E(d)-A_d(k)=825\,m$, where the window length is $n=100m$.
\end{theorem}
\begin{proof} By Theorem~\ref{thm:bridge}, $2(E-A_d(k))=\sum_v v^2N^{\mathrm{cyc}}_d(k,v)=m\sum_v v^2P_b(v)=m(b^4-b^2)/6$ by Theorem~\ref{thm:nullmom}; multiply by $6$. \end{proof}

No structural hypothesis on the melody enters; a measured deficit differing from $825m$ is the only legitimate form of a ``lag-$k$ anomaly'' claim in base ten.

\section{The temporal variable: a tropical seminorm on the lag monoid}

\begin{definition}
$p\in\N$ is a \emph{unison lag} (a period) of $x$ if $x_i=x_{i+p}$ for all $i$. Write $U(x)$ for the set of unison lags.
\end{definition}

\begin{lemma}\label{lem:per}
$0\in U(x)$; $U(x)$ is closed under addition; if $p,q\in U(x)$ with $q\le p$ then $p-q\in U(x)$; and $p,q\in U(x)$ implies $q\bmod p\in U(x)$.
\end{lemma}
\begin{proof} Additivity and $0$ are immediate. For subtraction, apply $q$-periodicity at index $i+(p-q)$ to move between $x_{i+p-q}$ and $x_{i+p}=x_i$. The modulus statement follows by removing $\lfloor q/p\rfloor$ copies of $p$. \end{proof}

\begin{theorem}[gcd-closure]\label{thm:gcd}
If $p,q\in U(x)$ then $\gcd(p,q)\in U(x)$.
\end{theorem}
\begin{proof} Strong induction on $p$. If $p=0$ then $\gcd(0,q)=q$. Otherwise $\gcd(p,q)=\gcd(q\bmod p,\,p)$ with $q\bmod p<p$ and $q\bmod p\in U(x)$ by Lemma~\ref{lem:per}; apply the inductive hypothesis. This is the Euclidean algorithm run inside $U(x)$. \end{proof}

\begin{theorem}[Rigidity of the unison-lag monoid]\label{thm:rigid}
If $x$ has a positive period, then $U(x)=\{p : p_{\min}(x)\mid p\}$ where $p_{\min}(x)$ is the least positive period. If $x$ has no positive period, then $U(x)=\{0\}$. Moreover two coprime periods force $x$ to be constant.
\end{theorem}
\begin{proof} Multiples of a period are periods. Conversely if $p\in U(x)$ is positive, then $g=\gcd(p_{\min},p)\in U(x)$ is positive and $\le p_{\min}$, hence $g=p_{\min}$, hence $p_{\min}\mid p$. If $\gcd(p,q)=1$ then $1\in U(x)$ by Theorem~\ref{thm:gcd}, so $x_i=x_{i+1}$ for all $i$. \end{proof}

\begin{definition}
The \emph{lag spectrum} is $M_x(\ell)=\sup_i|x_i-x_{i+\ell}|$. For $x\in\mathcal D_b$ it satisfies $M_x(\ell)<b$, hence $M_x(\ell)\le 9$ in the decimal case.
\end{definition}

\begin{theorem}[Subadditivity]\label{thm:sub}
For $x\in\mathcal D_b$, $M_x(k+\ell)\le M_x(k)+M_x(\ell)$.
\end{theorem}
\begin{proof} Fix $i$ and route through position $i+k$ using \eqref{eq:tri}:
$|x_i-x_{i+k+\ell}|\le|x_i-x_{i+k}|+|x_{i+k}-x_{i+k+\ell}|\le M_x(k)+M_x(\ell)$; take the supremum over $i$. \end{proof}

\begin{theorem}[Kernel]
For $x\in\mathcal D_b$, $M_x(\ell)=0$ if and only if $\ell\in U(x)$.
\end{theorem}

Recall the tropical semiring $(\N\cup\{\infty\},\oplus,\odot)$ with $a\oplus c=\min(a,c)$ and $a\odot c=a+c$, whose multiplicative unit is $0$. Theorem~\ref{thm:sub} says that $\ell\mapsto M_x(\ell)$ is \emph{submultiplicative} for the tropical product, i.e.\ a tropical seminorm on the additive monoid of lags; its unit fibre is exactly $U(x)$, an additive submonoid which by Theorem~\ref{thm:rigid} is a monoid of multiples.

\begin{theorem}[Lag twelve, resolved]
Let $x$ be a decimal melody. If $M_x(12)=0$, then $p_{\min}(x)\mid 12$, every lag-$12$ pair sounds a unison, and no lag-$12$ pair sounds an octave. If $M_x(12)\ne0$, then some lag-$12$ pair sounds an interval of size between $1$ and $9$ semitones --- again never an octave.
\end{theorem}
\begin{proof} If $M_x(12)=0$ then $12\in U(x)$, so $p_{\min}\mid12$ and all lag-$12$ intervals vanish; none can equal $12$ since all are $\le9$. If every lag-$12$ interval were outside $[1,9]$, then all being $\le 9$ they would all be $0$, forcing $M_x(12)=0$. \end{proof}

\begin{proposition}[Subadditivity is strictly one-way]
$M_{s_{7,12}}(12)=7$ and $M_{s_{7,12}}(24)=0$.
\end{proposition}
\begin{proof} The first is Lemma~\ref{lem:sq}. For the second, $\lfloor(i+24)/12\rfloor=\lfloor i/12\rfloor+2$ has the same parity as $\lfloor i/12\rfloor$, so the melody is $24$-periodic. \end{proof}

\section{The pitch variable: complete decoupling}

\begin{definition}
Given a demand sequence $v:\N\to\N$, the \emph{alternating walk} is $W_v(0)=0$ and $W_v(t+1)=W_v(t)+v(t)$ for $t$ even, $W_v(t+1)=W_v(t)-v(t)$ for $t$ odd.
\end{definition}

\begin{lemma}[Walk invariant]\label{lem:walk}
If $v$ is non-increasing then $0\le W_v(t)\le v(0)$ for all $t$, and $|W_v(t+1)-W_v(t)|=v(t)$ for all $t$.
\end{lemma}
\begin{proof}[Proof sketch] Maintain by induction the parity invariant ``at even $t$: $W_v(t)+v(t)\le v(0)$; at odd $t$: $v(t)\le W_v(t)$'', using monotonicity of $v$ at each step. The invariant ensures the up-steps do not overshoot the ceiling $v(0)$ and the down-steps do not underflow $0$, so each step realizes its demand exactly. \end{proof}

\begin{definition}
For a multiplicity function $N$ on $\{0,\dots,9\}$ let the \emph{tail mass} be $T_N(w)=\sum_{u=w}^{9}N(u)$ and the \emph{layer sequence} be $L_N(t)=\#\{w\in\{1,\dots,9\} : t<T_N(w)\}$.
\end{definition}

\begin{lemma}[Layer-cake rearrangement]\label{lem:layer}
$L_N$ is non-increasing with values in $\{0,\dots,9\}$, and if $\sum_{v\le9}N(v)=n$ then $\#\{t<n : L_N(t)=w\}=N(w)$ for all $w\le9$.
\end{lemma}
\begin{proof}[Proof sketch] Monotonicity and the range bound are immediate since $T_N$ is antitone and there are nine levels. One first shows $\#\{t<n : L_N(t)\ge w\}=T_N(w)$ for $1\le w\le 9$, the defining property of a layer cake, then subtracts consecutive upper level sets using $T_N(w)=N(w)+T_N(w+1)$ and $T_N(10)=0$; the case $w=0$ is the complement of the first upper level set. \end{proof}

\begin{theorem}[Inverse theorem]\label{thm:inv}
Let $N$ be a multiplicity function on $\{0,\dots,9\}$ with $\sum_{v}N(v)=n$. Then the decimal melody $x=W_{L_N}$ satisfies $N_x(n,1,w)=N(w)$ for all $w\le9$.
\end{theorem}
\begin{proof} By Lemma~\ref{lem:layer}, $L_N$ is non-increasing with values $\le9$, so by Lemma~\ref{lem:walk} the walk stays in $[0,L_N(0)]\subseteq[0,9]$ and its lag-$1$ interval at time $t$ is exactly $L_N(t)$. The lag-$1$ histogram is therefore the value histogram of $L_N$, which is $N$. \end{proof}

\begin{corollary}
There is a decimal melody realizing, in a window of ten position pairs, one unison and nine intervals of nine semitones each --- and still no octave.
\end{corollary}

\begin{definition}
For $\ell\ge1$ the \emph{$\ell$-fold interleaving} of $z$ is $z^{[\ell]}(i)=z(\lfloor i/\ell\rfloor)$: $\ell$ independent voices, each advancing one step per $\ell$ time units. It satisfies $\lambda_{z^{[\ell]}}(\ell,i)=\lambda_z(1,\lfloor i/\ell\rfloor)$.
\end{definition}

\begin{theorem}[Decoupling at every lag]\label{thm:decouple}
Let $\ell\ge1$ and let $N$ be a multiplicity function on $\{0,\dots,9\}$ of total mass $m$. Then there is a decimal melody $x$ with $N_x(\ell m,\ell,w)=\ell\,N(w)$ for all $w\le9$.
\end{theorem}
\begin{proof} Take $x=(W_{L_N})^{[\ell]}$. The window splits into $m$ blocks $[\ell t,\ell t+\ell)$, and on block $t$ every one of the $\ell$ positions realizes the same interval $\lambda_{W_{L_N}}(1,t)$. Summing block contributions and applying Theorem~\ref{thm:inv} gives $\ell N(w)$. \end{proof}

Consequently, for every lag $\ell\ge1$ every histogram supported on $\{0,\dots,9\}$ occurs (scaled by $\ell$) as a lag-$\ell$ interval distribution, and no histogram charging $v\ge10$ is attainable. \emph{Lags are rigid, pitches are free, and the only coupling is the second moment.}

\section{The min-plus interval matrix}

\begin{definition}
For a melody $x$ and $n\ge1$, the \emph{interval matrix} $A$ has entries $A_{ij}=|x_i-x_j|$, read in the min-plus semiring, where $(A\odot B)_{ij}=\min_k(A_{ik}+B_{kj})$.
\end{definition}

\begin{lemma}[Chain bound]
For positions $p_0,\dots,p_m$, $\ |x_{p_0}-x_{p_m}|\le\sum_{t<m}|x_{p_t}-x_{p_{t+1}}|$.
\end{lemma}
\begin{proof} Induction on $m$ using \eqref{eq:tri}. \end{proof}

\begin{theorem}[Tropical idempotency]
$A\odot A=A$, hence $A^{\odot m}=A$ for every $m\ge1$.
\end{theorem}
\begin{proof} ``$\le$'': choose $k=i$, of cost $A_{ii}+A_{ij}=A_{ij}$. ``$\ge$'': $A_{ik}+A_{kj}\ge A_{ij}$ for every $k$ by \eqref{eq:tri}; take the minimum. \end{proof}

Musically: $(A\odot A)_{ij}$ is the cheapest two-step voice-leading from note $i$ to note $j$ through an intermediate note, and idempotency says the cheapest voice-leading with any number of stops is the direct interval; the interval matrix is its own tropical Kleene closure. It is symmetric, its diagonal is the tropical unit, and for decimal melodies every entry is $\le9$ and no entry equals $12$ --- including the entries at the pair $(i,i+12)$, where the entry equals the lag-$12$ interval and never the octave.

\section{Pitch classes modulo twelve}

\begin{theorem}[Faithfulness below the octave]
If $a,c<12$ then $\pc(a)=\pc(c)$ if and only if $a=c$, where $\pc(a)=a\bmod 12$.
\end{theorem}

\begin{corollary}
For decimal melodies, two notes have the same pitch class exactly when they are the same note, and two pairs have the same interval class $\ic(a,c)=\pc(|a-c|)$ exactly when they have the same interval. Octave equivalence is a no-op on the digit scale.
\end{corollary}

\begin{theorem}[Sharpness]
In base $13$ the reduction fails to be injective: $\pc(0)=\pc(12)$ while $0\ne12$.
\end{theorem}

So mod-$12$ analysis and interval analysis are the same theory for alphabets of at most twelve symbols and genuinely diverge from thirteen symbols on. On a decimal digit scale, ``using pitch classes'' is not a correction; the real correction is to measure $|x_i-x_j|$ for a clearly specified pair of positions.

\section{Algorithms}

\begin{algorithmx}[Interval histogram at a lag]
Given a window $x_0,\dots,x_{n+\ell-1}$ and a lag $\ell$, initialize $H[0..b-1]\leftarrow0$ and for $i=0,\dots,n-1$ increment $H[\,|x_i-x_{i+\ell}|\,]$. Cost $O(n)$ time, $O(b)$ space; the output has mass $n$ and support in $\{0,\dots,b-1\}$.
\end{algorithmx}

\begin{algorithmx}[Moment-bridge audit and null test]
Given a cyclic window $d$ of length $n$ and a lag $k$, compute $E=\sum d_i^2$, $A=\sum d_id_{i+k}$, and the cyclic histogram $H$; verify $2A=2E-\sum_v v^2H[v]$, whose residual is identically zero. Comparing $E-A$ with $825m$ (where $n=100m$) implements the null deficit test. Cost $O(n+b)$.
\end{algorithmx}

\begin{algorithmx}[Histogram realization]
Given a target histogram $N$ on $\{0,\dots,9\}$ of mass $n$ and a lag $\ell\ge1$: compute the tail masses $T_N(w)$; form $L_N(t)=\#\{w : t<T_N(w)\}$ for $t<n$; run the alternating walk $W_{L_N}$; if $\ell>1$, interleave to $x(i)=W_{L_N}(\lfloor i/\ell\rfloor)$, giving a window of length $\ell n$ whose lag-$\ell$ histogram is $\ell N$. Cost $O(\ell n)$.
\end{algorithmx}

\section{Applications and discussion}

\emph{Reporting standards.} A claim about musical content in a digit sequence should report the interval histogram at an explicitly stated lag and window, not a correlation coefficient; the moment bridge fixes what a correlation means. \emph{Exact baselines.} Theorem~\ref{thm:deficit} replaces Monte Carlo baselines by an identity: a decimal window of length $100m$ with the triangular null histogram has autocorrelation deficit exactly $825m$. \emph{Alphabet choice.} A study that genuinely wishes to test octave phenomena needs at least thirteen symbols. \emph{Periodicity detection.} Rigidity implies the set of perfectly correlated lags is divisibility-closed, so a detected unison lag determines all of them; and two coprime detected periods imply constancy, a cheap consistency test. \emph{Voice leading.} Idempotency of the interval matrix says shortest-path closure is trivial in a one-dimensional pitch space; nontrivial voice-leading geometry requires a pitch space that is not a line.

The overall shape of the theory is an asymmetry. The temporal variable lives in $(\N,+)$, is measured by a subadditive scalar, and is organized by divisibility. The pitch variable lives in $\{0,\dots,b-1\}$ and is unconstrained beyond its support. The only bridge is the second moment, and Theorem~\ref{thm:loss} shows the resulting information loss is already realized on windows of length four. Two caveats delimit the scope: the ``no octave'' statements are properties of the alphabet, not of any particular sequence, and faithfulness of pitch-class reduction is likewise an artefact of alphabet size. At the degenerate lag $\ell=0$ the histogram is a point mass at the unison for trivial reasons, which is why Theorem~\ref{thm:spec} is a guarded biconditional.

\section{Future directions}

\begin{conjecture}[Tropical spectral rigidity]
For aperiodic decimal melodies of positive entropy, $\ell\mapsto M_x(\ell)$ is eventually equal to its maximum $9$, and the set of lags where it is $<9$ is finite and closed under divisors.
\end{conjecture}
The key insight is that $M_x$ is a tropical seminorm on $(\N,+)$ whose unit fibre is an arithmetically rigid monoid, so the level sets $\{\ell : M_x(\ell)\le c\}$ should inherit divisor-closedness from the same subtraction argument that produced gcd-closure. Subadditivity, gcd-closure, and the description of the unison lags supply the case $c=0$ in full; the general case needs a quantitative ``$c$-approximate period'' calculus.

\begin{conjecture}[Fine--Wilf theorem for finite digit windows]
If a window of $n$ consecutive digits has unison lags $p$ and $q$ and $n\ge p+q-\gcd(p,q)$, then it has unison lag $\gcd(p,q)$; the bound is sharp.
\end{conjecture}
The infinite-word gcd-closure proved here degenerates on finite windows exactly at the Fine--Wilf threshold, so the finite theorem is the quantitative refinement of the rigidity already established. A finite-window version is what empirical digit studies actually measure, and the proof can reuse the period-subtraction lemma with an index-range side condition.

\begin{conjecture}[Joint interval distributions at two lags]
For coprime lags $k,\ell\ge1$ the pair $(N_k,N_\ell)$ is jointly realizable for every pair of admissible histograms of equal mass, whereas for $\ell=2k$ the pair is constrained by the tropical triangle inequality: $N_{2k}$ is supported in $[0,2\max\supp N_k]$.
\end{conjecture}
Interleaving, used here for a single lag, becomes a Chinese-remainder construction for coprime lags, while non-coprime lags are coupled by subadditivity of the lag spectrum --- so coprimality is exactly the boundary between free and constrained joint realizability.

\section{Conclusion}

Autocorrelation at sequence lag $12$ compares digit positions twelve time steps apart; it does not measure a twelve-semitone interval. Once the two variables are separated, each acquires a clean theory: the temporal variable becomes a tropical seminorm on the lag monoid with a divisibility-rigid kernel, and the pitch variable becomes a free histogram constrained only by the alphabet's span. The unique bridge between them, the second moment, is explicit, non-invertible, and carries an exact combinatorial null baseline. To study musical intervals in a digit sequence, use the distribution of $|x_i-x_j|$ for a clearly specified pair of positions --- and if octaves are the object of interest, use an alphabet with at least thirteen symbols.

